def comment_tag(d, n):
    v = d.args[n].value
    if v >= 10:
        d.args[n].print += f' (смартфон {v - 9})'


def comment(d, n, desc):
    v = d.args[n].value
    if v in desc:
        d.args[n].print += f' ({desc[v]})'


def comment_tag0(d):
    comment_tag(d, 0)


def comment_tag1(d):
    comment_tag(d, 1)


def comment_ev0(d):
    comment(d, 0, event_desc)


def comment_ev0_src1_cmd2(d):
    comment(d, 0, event_desc)
    comment(d, 1, src_desc)
    comment(d, 2, cmd_desc)


def comment_ev0_cmd2(d):
    comment(d, 0, event_desc)
    comment(d, 2, cmd_desc)


def comment_ev1(d):
    comment(d, 1, event_desc)


def comment_ev3(d):
    comment(d, 3, event_desc)


def comment_cmd0(d):
    comment(d, 0, cmd_desc)


def comment_tag0_cmd1(d):
    comment_tag(d, 0)
    comment(d, 1, cmd_desc)


def comment_src1_cmd2_ev3(d):
    comment(d, 1, src_desc)
    comment(d, 2, cmd_desc)
    comment(d, 3, event_desc)


def comment_rem0(d):
    comment(d, 0, cmd_rem)


def comment_cansts0_state1(d):
    comment(d, 0, cansts_desc)
    comment(d, 1, cansts_state_desc)


def comment_pwr0_pwr1(d):
    comment(d, 0, pwr_src)
    comment(d, 1, pwr_src)


def split_line(d, n, p):
    lines = d.args[n].value.split('\\n')
    if len(lines) > 1:
        prefix_len = p + sum(d.line.TAB_POS[s] for s in d.line.TAB_POS if d.line.parser.field(s))
        suffix_len = 100 - p-len(lines[-1]) if d.line.parser.field_d else 0
        d.args[n].print = ('\n' + ' ' * prefix_len).join(lines) + (' ' * suffix_len)


def multiline_sms(d):
    split_line(d, 1, len(d.args[0].value))


def multiline_ussd(d):
    split_line(d, 0, d.string.index('{}'))
